    def get_trading_day(self, day=0):
        """
        获取交易日
        :param day: 表示天数，正的为数天后，负的为数天前，day取0表示获取当前交易日，
                    如果当前日期为非交易日则返回下一交易日的日期。day默认取值为0，
                    不建议获取交易所还未公布的交易日期；
        :type day: :int

        :return value: 指定交易日
        :type: : datetime
        """
        trading_days = self.api.get_trading_day()
        today = datetime.date.today()
        day = -2
        if today in trading_days:
            if day == 0:
                return today
            else:
                return trading_days[trading_days.index(today) + day]
        else:
            trading_days = pd.DataFrame(index=trading_days)
            if day == 0:
                day = 1
            if day > 0:
                return trading_days[today:].index[day - 1]
            elif day < 0:
                return trading_days[:today].index[day]
