    def get_stock_name(self, stocks):
        """
        获取股票名称
        :param stocks: 股票代码
        :rtype stocks: str or list
        :return: dict
        """
        re_data = {}
        if isinstance(stocks, six.string_types):
            stocks = [stocks]
        for stock in stocks:
            data = self.api.get_security_info(stock)
            if len(data) > 0:
                if stock in data.keys():
                    re_data[stock] = data[stock].get('name')
                    continue
                re_data[stock] = None
        else:
            return re_data
    def get_stock_info(self, stocks, field=None):
        """
        获取股票基础信息
        :param stocks: stocks：股票代码，str或list类型
        :param field：指明数据结果集中所支持输出字段，list或str类型，输出字段包括：
            stock_name -- 股票代码对应公司名；
            listed_date -- 股票上市日期；
            de_listed_date -- 股票退市日期，若未退市，返回2900-01-01；
        :return: 嵌套dict
        """
        re_data = {}
        if isinstance(stocks, six.string_types):
            stocks = [stocks]
        if field is None:
            field = ['stock_name']
        elif isinstance(field, str):
            field = [field]
        data = self.api.get_security_info(stocks)
        for stock in stocks:
            tem_dict = {}
            if data.get(stock, {}):
                try:
                    data_trans = {'stock_name': data[stock]['name'], 'listed_date': data[stock]['listed_date'].strftime('%Y-%m-%d'), 'de_listed_date': '2900-01-01' if data[stock]['delisted_date'] > datetime.datetime.now() else data[stock]['delisted_date'].strftime('%Y-%m-%d')}
                    for item in field:
                        value = data_trans.get(item, None)
                        tem_dict[item] = value
                except KeyError as e:
                    system_log.warning(get_traceback_message())
            re_data[stock] = tem_dict
        else:
            return re_data
